// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // A non-privileged actor attempts to pause the contract; the call must fail
        // (no MANAGER role is configured), so the paused state must remain unchanged.
        vm.prank(actor);
        bool ok;
        try c.pause() { ok = true; } catch { ok = false; }
        assertFalse(ok, "pause unexpectedly succeeded");
        // General rule: since no pause was ever successfully performed, paused()
        // must report the actual (unchanged) paused state, i.e. false.
        // The mutant negates the flag and returns true, breaking the rule.
        assertTrue(c.paused() == false, "paused() must reflect the unpaused state");
    }
}
